CREATE TABLE IF NOT EXISTS provider_configs(provider TEXT PRIMARY KEY,config_json TEXT NOT NULL,encrypted_key TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS search_jobs(id TEXT PRIMARY KEY,query TEXT,country TEXT,language TEXT,status TEXT,result_count INTEGER DEFAULT 0,estimated_cost REAL DEFAULT 0,actual_cost REAL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS provider_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,job_id TEXT,provider TEXT,status TEXT,duration_ms INTEGER DEFAULT 0,result_count INTEGER DEFAULT 0,estimated_cost REAL DEFAULT 0,error TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY,url TEXT UNIQUE,domain TEXT,title TEXT,snippet TEXT,country TEXT,providers_json TEXT,ranks_json TEXT,score INTEGER DEFAULT 0,score_reasons TEXT,status TEXT DEFAULT 'new',notes TEXT DEFAULT '',tags TEXT DEFAULT '[]',emails TEXT DEFAULT '[]',phones TEXT DEFAULT '[]',socials TEXT DEFAULT '[]',raw_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
